function pageHero(title,desc){const bn=BANNERS[page];const bnUrl=bn?new URL(bn,document.baseURI).href:'';return `<section class="page-hero${bn?' has-banner':''}"${bn?` style="--banner:url('${bnUrl}')"`:''}><div class="page-hero-inner"><div class="breadcrumbs"><a href="${ROOT}index.html">Home</a><span>/</span><span>${title}</span></div><span class="eyebrow">Wavecrest Swimming Academy</span><h1>${title}</h1><p>${desc}</p></div></section>`}
function sectionIntro(kicker,title,copy,align=''){return `<div class="${align==='center'?'text-center section-intro-center':''}"><span class="eyebrow">${kicker}</span><h2 class="section-title ${align==='center'?'mx-auto':''}">${title}</h2><p class="section-copy ${align==='center'?'mx-auto':''}">${copy}</p></div>`}
function programCard(p){return `<article class="program-card"><img loading="lazy" src="${p.img||imgFallback}" alt="${p.title} swimming session"><div class="program-card-content"><div class="program-meta"><span>${p.group}</span><span>${p.level}</span></div><h3>${p.title}</h3><p>${p.desc}</p><a class="text-link" style="color:var(--aqua)" href="${PG}program-details.html?program=${p.id}">Explore programme ${icon('arrow-up-right')}</a></div></article>`}
function coachCard(c){return `<article class="content-card p-0 overflow-hidden"><img loading="lazy" src="${c.img}" alt="${c.name}, ${c.role}" style="height:270px;width:100%;object-fit:cover"><div class="p-4"><span class="eyebrow">${c.specialty}</span><h3 class="mt-2">${c.name}</h3><p class="mb-1">${c.role}</p><small style="color:var(--muted)">${c.experience}</small><div class="mt-3"><a class="text-link" href="${PG}coach-details.html?coach=${encodeURIComponent(c.name)}">Coach profile ${icon('arrow-up-right')}</a></div></div></article>`}
function home(){return `<section class="hero"><div class="hero-content"><span class="hero-kicker">Move with confidence</span><h1>Make every length a little more <span style="color:var(--aqua)">possible.</span></h1><p>Thoughtful swimming lessons for children, teens and adults — from first splash to stronger, more confident strokes.</p><div class="hero-actions"><a class="btn-aqua" href="${PG}programs.html">Explore programs ${icon('arrow-up-right')}</a><a class="btn-outline-custom" href="${PG}book-now.html">Book a trial session ${icon('calendar-days')}</a></div></div><div class="hero-stat"><strong>Every</strong><span>swimmer starts somewhere. We help you find the next step.</span></div></section><div class="trust-row"><div class="trust-item"><span class="trust-icon">${icon('users')}</span><div><strong>All ages welcome</strong><small>Kids, teens and adults</small></div></div><div class="trust-item"><span class="trust-icon">${icon('route')}</span><div><strong>Clear learning paths</strong><small>Small steps, visible progress</small></div></div><div class="trust-item"><span class="trust-icon">${icon('shield-check')}</span><div><strong>Safety-minded learning</strong><small>Skills built with awareness</small></div></div><div class="trust-item"><span class="trust-icon">${icon('calendar-check')}</span><div><strong>Organized sessions</strong><small>Find a batch that fits</small></div></div></div><section class="section-pad"><div class="container-fluid">${sectionIntro('Find your starting point','A programme for the swimmer you are today','Explore age-aware and skill-led sessions designed to help each swimmer build confidence and keep developing.','center')}<div class="program-grid mt-5">${D.programs.slice(0,3).map(programCard).join('')}</div><div class="text-center mt-4"><a class="btn-outline-custom" href="${PG}programs.html">View all programmes ${icon('arrow-up-right')}</a></div></div></section><section class="section-pad" style="background:var(--surface-soft)"><div class="container-fluid"><div class="split-feature"><div class="feature-photo"><img loading="lazy" src="${ROOT}assets/images/facilities/indoor-pool.jpg" alt="Swimming lesson taking place in an indoor pool"><div class="photo-note"><strong>Progress, not pressure.</strong><span>Supportive coaching at every stage</span></div></div><div><span class="eyebrow">A better way to learn</span><h2 class="section-title">Strong foundations make room for bigger goals.</h2><p class="section-copy">Our learning approach combines patient instruction, repeatable fundamentals and clear milestones. Whether a swimmer is meeting the water for the first time or refining a stroke, the next step should feel understandable.</p><div class="feature-list"><article><strong>Personal attention</strong><p>Coaching cues that meet the swimmer at their current level.</p></article><article><strong>Progress you can see</strong><p>Skill milestones that make learning easier to follow.</p></article><article><strong>Water awareness</strong><p>Pool habits and water-safety learning are part of the journey.</p></article><article><strong>Flexible pathways</strong><p>Options for recreational learning and performance goals.</p></article></div><a class="text-link" href="${PG}about.html">Discover our approach ${icon('arrow-up-right')}</a></div></div></div></section><section class="section-pad"><div class="container-fluid">${sectionIntro('The learning journey','Small milestones. Stronger swimmers.','Swimming is a collection of skills that build on one another. We make that progression clear, practical and encouraging.','center')}<div class="progress-track"><div class="progress-step"><div class="progress-dot">01</div><strong>Water confidence</strong><small>Get comfortable</small></div><div class="progress-step"><div class="progress-dot">02</div><strong>Core control</strong><small>Float & breathe</small></div><div class="progress-step"><div class="progress-dot">03</div><strong>Stroke basics</strong><small>Move with rhythm</small></div><div class="progress-step"><div class="progress-dot">04</div><strong>Build endurance</strong><small>Go further</small></div><div class="progress-step"><div class="progress-dot">05</div><strong>Refine technique</strong><small>Swim efficiently</small></div></div></div></section><section class="section-pad" style="background:var(--navy)"><div class="container-fluid"><div class="d-flex justify-content-between align-items-end flex-wrap gap-3 mb-4"><div><span class="eyebrow" style="color:var(--aqua)">The people behind the progress</span><h2 class="section-title" style="color:#fff;margin-bottom:0">Meet your coaching team.</h2></div><a href="${PG}coaches.html" class="btn-outline-custom" style="color:#fff;border-color:rgba(255,255,255,.4)">Meet all coaches ${icon('arrow-up-right')}</a></div><div class="row g-4 home-coaches">${D.coaches.slice(0,3).map(c=>`<div class="col-md-4">${coachCard(c)}</div>`).join('')}</div></div></section><section class="section-pad"><div class="container-fluid"><div class="split-feature"><div><span class="eyebrow">Make time for the water</span><h2 class="section-title">A weekly rhythm that works for you.</h2><p class="section-copy">Browse sessions by day, age group and programme.</p><a href="${PG}batch-timings.html" class="btn-primary-custom mt-3">View weekly timetable ${icon('arrow-up-right')}</a></div><div class="schedule-preview"><h2 class="h3 mb-3">This week at Wavecrest</h2>${D.batches.slice(0,4).map(b=>`<div class="schedule-row"><strong>${b.day}</strong><span>${b.program}<br><small>${b.time}</small></span><span class="schedule-coach">${b.coach}</span><span class="schedule-pill">${b.status}</span></div>`).join('')}</div></div></div></section><section class="section-pad" style="background:var(--surface-soft)"><div class="container-fluid">${sectionIntro('Learning well means learning thoughtfully','Water awareness belongs in every lesson','We introduce pool awareness, listening for instructions, entry and exit habits, and a gradual approach to skills. Lessons are not a substitute for active adult supervision around water.','center')}<div class="row g-4 mt-3"><div class="col-md-4"><div class="content-card"><span class="trust-icon">${icon('waves')}</span><h3 class="mt-3">Know the environment</h3><p>Learn pool rules, depth awareness, safe entry and exit routines, and where to ask for help.</p></div></div><div class="col-md-4"><div class="content-card"><span class="trust-icon">${icon('life-buoy')}</span><h3 class="mt-3">Build practical skills for swimming</h3><p>Practice age-appropriate water confidence and swimming fundamentals under coach guidance.</p></div></div><div class="col-md-4"><div class="content-card"><span class="trust-icon">${icon('hand-heart')}</span><h3 class="mt-3">Keep learning supported</h3><p>Progress is reviewed by coaches and developed at a pace suited to the swimmer.</p></div></div></div></div></section><section class="section-pad"><div class="container-fluid"><div class="d-flex justify-content-between align-items-end flex-wrap gap-3 mb-4"><div><span class="eyebrow">From our community</span><h2 class="section-title mb-0">Good experiences travel.</h2></div></div><div class="row g-4"><div class="col-md-4"><div class="testimonial"><div class="stars">★★★★★</div><blockquote>“The lessons gave our daughter a calm place to practise and celebrate the little wins.”</blockquote><div class="testimonial-person"><img src="${ROOT}assets/images/community/parent-1.jpg" alt="Parent" width="56" height="56" loading="lazy"><div><strong>Paul</strong><small>Parent review</small></div></div></div></div><div class="col-md-4"><div class="testimonial"><div class="stars">★★★★★</div><blockquote>“I finally feel comfortable asking questions and working on the basics at my own pace.”</blockquote><div class="testimonial-person"><img src="${ROOT}assets/images/community/adult-1.jpg" alt="Adult swimmer" width="56" height="56" loading="lazy"><div><strong>John</strong><small>Adult swimmer review</small></div></div></div></div><div class="col-md-4"><div class="testimonial"><div class="stars">★★★★★</div><blockquote>“The coaching feedback is clear, practical and easy to work on between sessions.”</blockquote><div class="testimonial-person"><img src="${ROOT}assets/images/community/member-1.jpg" alt="Academy member" width="56" height="56" loading="lazy"><div><strong>William</strong><small>Member review</small></div></div></div></div></div></div></section><section class="section-pad-sm"><div class="container-fluid"><div class="d-flex justify-content-between align-items-end flex-wrap gap-3 mb-4"><div><span class="eyebrow">Inside the academy</span><h2 class="section-title mb-0">A closer look at pool life.</h2></div><a class="text-link" href="${PG}gallery.html">Explore the gallery ${icon('arrow-up-right')}</a></div><div class="gallery-grid"><button data-lightbox="${ROOT}assets/images/facilities/indoor-pool.jpg"><img loading="lazy" src="${ROOT}assets/images/facilities/indoor-pool.jpg" alt="Indoor swimming pool"></button><button data-lightbox="${ROOT}assets/images/gallery/swimming-practice.jpg"><img loading="lazy" src="${ROOT}assets/images/gallery/swimming-practice.jpg" alt="Swimmer in the pool"></button><button data-lightbox="${ROOT}assets/images/gallery/poolside-learning.jpg"><img loading="lazy" src="${ROOT}assets/images/gallery/poolside-learning.jpg" alt="Poolside swimming activity"></button><button data-lightbox="${ROOT}assets/images/gallery/training-sessions.jpg"><img loading="lazy" src="${ROOT}assets/images/gallery/training-sessions.jpg" alt="Swimming training"></button><button data-lightbox="${ROOT}assets/images/facilities/performance-pool.jpg"><img loading="lazy" src="${ROOT}assets/images/facilities/performance-pool.jpg" alt="Competition swimming pool"></button></div></div></section><section class="cta-band"><div><h2>Ready to find your next step?</h2><p>Tell us a little about the swimmer and we’ll help you explore the right programme.</p></div><a class="btn-aqua" href="${PG}book-now.html">Book a trial session ${icon('arrow-up-right')}</a></section>`}
function home2(){const U=(id,w)=>`${ROOT}assets/images/${id}.jpg`;const coach=D.coaches[0]||{name:'Head Coach',role:'Performance lead'};return `<section class="hero-2"><div class="hero-2-copy"><span class="eyebrow">For every age. For every ambition.</span><h1>From first splash to confident stroke.</h1><p class="section-copy">A swimming journey shaped around the person in the water — playful beginnings, steady learning and purposeful performance training.</p><div class="hero-actions"><a class="btn-primary-custom" href="${PG}programs.html">Find your programme ${icon('arrow-up-right')}</a><a class="btn-outline-custom" href="${PG}book-now.html">Book a trial</a></div></div><div class="hero-2-media" role="img" aria-label="Bright indoor swimming pool"></div></section>
<section class="h2-stats"><div class="h2-stat"><strong>6</strong><span>lanes in the main pool</span></div><div class="h2-stat"><strong>4–70</strong><span>age range we teach</span></div><div class="h2-stat"><strong>5</strong><span>One pathway</span></div><div class="h2-stat"><strong>7 days</strong><span>of sessions each week</span></div></section>
<section class="section-pad"><div class="container-fluid">${sectionIntro('The squad ladder','Five squads. One clear way up.','Every swimmer joins at the rung that fits today and moves up when the coach sees the skills are ready — not when the calendar says so.','center')}<div class="h2-ladder">
<a class="h2-rung" href="${PG}program-details.html?program=kids"><span class="h2-rung-no">01</span><div><h3>Splash</h3><p>Water confidence through play, songs and guided floating.</p></div><span class="h2-rung-tag">Ages 4–7</span><span class="h2-rung-go">${icon('arrow-up-right')}</span></a>
<a class="h2-rung" href="${PG}program-details.html?program=kids"><span class="h2-rung-no">02</span><div><h3>Glide</h3><p>Kicking, streamline and first full strokes with a buddy-coach ratio.</p></div><span class="h2-rung-tag">Ages 8–12</span><span class="h2-rung-go">${icon('arrow-up-right')}</span></a>
<a class="h2-rung" href="${PG}program-details.html?program=teens"><span class="h2-rung-no">03</span><div><h3>Stroke</h3><p>Four-stroke technique, breathing patterns and pacing drills.</p></div><span class="h2-rung-tag">Ages 13–17</span><span class="h2-rung-go">${icon('arrow-up-right')}</span></a>
<a class="h2-rung" href="${PG}program-details.html?program=adult-beginner"><span class="h2-rung-no">04</span><div><h3>Masters</h3><p>Evening swims for adults who want fitness, technique or a calm return to the water.</p></div><span class="h2-rung-tag">Adults 18+</span><span class="h2-rung-go">${icon('arrow-up-right')}</span></a>
<a class="h2-rung" href="${PG}program-details.html?program=competitive"><span class="h2-rung-no">05</span><div><h3>Performance</h3><p>Pace sets, turns, starts and race preparation for committed swimmers.</p></div><span class="h2-rung-tag">Ages 12–18</span><span class="h2-rung-go">${icon('arrow-up-right')}</span></a>
</div></div></section>
<section class="section-pad" style="background:var(--surface-soft)"><div class="container-fluid"><div class="split-feature"><div><span class="eyebrow">Inside one lesson</span><h2 class="section-title">Sixty minutes, planned to the minute.</h2><p class="section-copy">Parents often ask what actually happens poolside. Here is the rhythm of a typical session — the same shape every week, so swimmers always know what comes next.</p><ol class="h2-timeline"><li><b>0–10</b><div><strong>Poolside welcome</strong><span>Name check, goals for the day, goggles on.</span></div></li><li><b>10–20</b><div><strong>Warm-up</strong><span>Easy lengths and buoyancy games to settle in.</span></div></li><li><b>20–40</b><div><strong>Skill block</strong><span>One focus skill, broken into short repeatable drills.</span></div></li><li><b>40–50</b><div><strong>Challenge</strong><span>Relays, races or games that put the skill to use.</span></div></li><li><b>50–60</b><div><strong>Cool-down &amp; note</strong><span>A quick coach note on what to practise next.</span></div></li></ol></div><div class="feature-photo h2-photo"><img loading="lazy" src="${U('gallery/swimming-practice',1300)}" alt="Swimmer practising during a coached lesson"><div class="photo-note"><strong>Same rhythm, every week.</strong><span>Predictable sessions build calm swimmers</span></div></div></div></div></section>
<section class="section-pad"><div class="container-fluid"><div class="d-flex justify-content-between align-items-end gap-3 flex-wrap mb-4"><div><span class="eyebrow">Beyond the lesson</span><h2 class="section-title mb-0">More ways to share the water.</h2></div><a href="${PG}pricing.html" class="text-link">Compare plans ${icon('arrow-up-right')}</a></div><div class="h2-bento">
<a class="h2-tile h2-tile-lg" href="${PG}programs.html?group=Kids"><img loading="lazy" src="${U('gallery/poolside-learning',1100)}" alt="Parent and child in the pool"><div><span>Parent &amp; child</span><h3>Splash together</h3></div></a>
<a class="h2-tile" href="${PG}programs.html?group=Adults"><img loading="lazy" src="${U('gallery/training-sessions',800)}" alt="Adult swimmers training"><div><span>Evenings</span><h3>Masters lanes</h3></div></a>
<a class="h2-tile" href="${PG}programs.html"><img loading="lazy" src="${U('facilities/indoor-pool',800)}" alt="Family swimming in an indoor pool"><div><span>Weekends</span><h3>Family swim</h3></div></a>
<a class="h2-tile h2-tile-wide" href="${PG}contact.html"><img loading="lazy" src="${U('facilities/performance-pool',1100)}" alt="Holiday swimming camp in the pool"><div><span>School breaks</span><h3>Holiday camps</h3></div></a>
</div></div></section>
<section class="section-pad h2-perf"><div class="container-fluid"><div class="h2-perf-grid"><div><span class="eyebrow" style="color:var(--aqua)">Performance pathway</span><h2 class="section-title" style="color:#fff">Race-ready, one length at a time.</h2><p style="color:rgba(255,255,255,.72)">For swimmers who want to train with intent. The Performance squad builds the habits behind faster, more controlled racing.</p><ul class="h2-checks"><li>${icon('timer')}<span>Pace sets and interval training</span></li><li>${icon('flag')}<span>Starts, turns and finishes</span></li><li>${icon('dumbbell')}<span>Dryland strength and mobility</span></li><li>${icon('medal')}<span>Meet preparation and race plans</span></li></ul><a class="btn-aqua mt-3" href="${PG}program-details.html?program=competitive">See the squad ${icon('arrow-up-right')}</a></div><figure class="h2-quote"><blockquote>“Fast swimming is mostly good habits repeated. We make those habits easy to see, and easy to practise.”</blockquote><figcaption><strong>${coach.name}</strong><span>${coach.role}</span></figcaption><a class="text-link" href="${PG}coaches.html">Meet the coaches ${icon('arrow-up-right')}</a></figure></div></div></section>
<section class="section-pad h2-faq-section"><div class="container-fluid"><div class="h2-faq-wrap">${sectionIntro('Parent questions','Things families ask before the first lesson.','Straight answers to the questions we hear most.','center')}<div class="h2-faq-cards"><details class="h2-q" open><summary><span class="h2-q-num">01</span><span class="h2-q-text">What should my child bring?</span><span class="h2-q-icon" aria-hidden="true"></span></summary><div class="h2-q-body"><p>Swimwear, a towel, goggles and a water bottle. Long hair should be tied back or covered with a swim cap.</p></div></details><details class="h2-q"><summary><span class="h2-q-num">02</span><span class="h2-q-text">Can I stay and watch?</span><span class="h2-q-icon" aria-hidden="true"></span></summary><div class="h2-q-body"><p>Yes. Parents are welcome in the viewing area, and we share a short coach note after each session.</p></div></details><details class="h2-q"><summary><span class="h2-q-num">03</span><span class="h2-q-text">How are swimmers placed in a squad?</span><span class="h2-q-icon" aria-hidden="true"></span></summary><div class="h2-q-body"><p>A coach observes a short trial session and recommends the squad that matches current skills and confidence.</p></div></details><details class="h2-q"><summary><span class="h2-q-num">04</span><span class="h2-q-text">What if we miss a lesson?</span><span class="h2-q-icon" aria-hidden="true"></span></summary><div class="h2-q-body"><p>Ask the front desk about catch-up options. Availability depends on space in the relevant squad.</p></div></details><details class="h2-q"><summary><span class="h2-q-num">05</span><span class="h2-q-text">Do you teach complete beginners who are adults?</span><span class="h2-q-icon" aria-hidden="true"></span></summary><div class="h2-q-body"><p>Absolutely. Masters lanes include a beginner-friendly start with small groups and a patient pace.</p></div></details><details class="h2-q"><summary><span class="h2-q-num">06</span><span class="h2-q-text">Do you offer a trial session?</span><span class="h2-q-icon" aria-hidden="true"></span></summary><div class="h2-q-body"><p>Yes. Book a trial through the Book Now form and a coach will observe the swimmer and suggest a suitable squad.</p></div></details></div><div class="h2-faq-foot"><div><strong>Still wondering about something?</strong><span>Our front desk replies within one working day.</span></div><a class="btn-outline-custom" href="${PG}contact.html">Ask us something else</a></div></div></div></section>
<section class="cta-band"><div><h2>Pick your lane. We’ll hold a spot.</h2><p>Book a trial session and a coach will help you choose the right squad.</p></div><a class="btn-aqua" href="${PG}book-now.html">Book a trial ${icon('arrow-up-right')}</a></section>`}
function programs(){return `${pageHero('Swimming programmes for every stage','Choose by age group and current ability.') }<section class="section-pad"><div class="container-fluid"><div class="d-flex justify-content-between flex-wrap align-items-end gap-3"><div>${sectionIntro('Find your fit','Start with the swimmer, not the label','Browse the options, compare learning focus and choose a starting point to discuss with the coaching team.')}</div><div class="d-flex gap-2 flex-wrap"><select class="form-select" id="programGroup" style="width:150px"><option value="all">All ages</option><option>Kids</option><option>Teens</option><option>Adults</option></select><select class="form-select" id="programLevel" style="width:170px"><option value="all">All skill levels</option><option>Beginner</option><option>Intermediate</option><option>Advanced</option><option>Competitive</option></select></div></div><div class="program-grid mt-5" id="programGrid">${D.programs.map(programCard).join('')}</div></div></section><section class="cta-band"><div><h2>Not sure where to begin?</h2><p>Share the swimmer’s experience and goals. We’ll help you explore the options.</p></div><a class="btn-aqua" href="${PG}book-now.html">Request a trial ${icon('arrow-up-right')}</a></section>`}
function programDetails(){let id=new URLSearchParams(location.search).get('program')||'kids',p=D.programs.find(x=>x.id===id)||D.programs[0];return `${pageHero(p.title, p.desc)}<section class="section-pad"><div class="container-fluid"><div class="split-feature"><div class="feature-photo"><img src="${p.img}" alt="${p.title} programme"></div><div><span class="eyebrow">${p.group} · ${p.level}</span><h2 class="section-title">A structured way to build your next skill.</h2><p class="section-copy">This programme gives swimmers a clear learning focus, practice time and coach feedback. The final placement should be confirmed through an assessment or conversation with the academy.</p><div class="feature-list"><article><strong>Age group</strong><p>${p.age}</p></article><article><strong>Programme length</strong><p>${p.duration}</p></article><article><strong>Fee</strong><p>${p.fee}</p></article><article><strong>Learning focus</strong><p>${p.level}</p></article></div><a href="${PG}book-now.html?program=${p.id}" class="btn-primary-custom">Enrol your interest ${icon('arrow-up-right')}</a></div></div><div class="row g-4 mt-5"><div class="col-lg-7"><div class="content-card"><h3>What swimmers work on</h3><ul><li>Water confidence and awareness appropriate to the swimmer’s level.</li><li>Floating, breathing control and body position.</li><li>Coordinated movement and foundational stroke technique.</li><li>Review of learning goals and coach feedback.</li></ul></div></div><div class="col-lg-5"><div class="soft-panel"><h3>Before your first session</h3><p>Bring swimwear, a towel and any academy-required equipment. Ask the team about facility-specific requirements, pool rules and arrival instructions.</p><a href="${PG}contact.html" class="text-link">Ask a question ${icon('arrow-up-right')}</a></div></div></div></div></section>`}
function coachDetails(){let name=new URLSearchParams(location.search).get('coach')||D.coaches[0].name;let c=D.coaches.find(x=>x.name===name)||D.coaches[0];return `${pageHero(c.name,c.role+' · '+c.specialty)}<section class="section-pad"><div class="container-fluid"><div class="split-feature"><div class="feature-photo"><img src="${c.img}" alt="${c.name}, ${c.role}"></div><div><span class="eyebrow">${c.specialty}</span><h2 class="section-title">Coaching with clarity, care and purpose.</h2><p class="section-copy">${c.bio}</p><div class="feature-list"><article><strong>Role</strong><p>${c.role}</p></article><article><strong>Experience</strong><p>${c.experience}</p></article><article><strong>Focus</strong><p>${c.specialty}</p></article></div><a href="${PG}book-now.html" class="btn-primary-custom">Ask about a programme ${icon('arrow-up-right')}</a></div></div><div class="soft-panel mt-5"><h3>Coaching approach</h3><p>Each swimmer works through an appropriate set of skill goals. The coach provides feedback and records assessments for the academy to share with the swimmer or parent/guardian.</p><a class="text-link" href="${PG}coaches.html">Back to all coaches ${icon('arrow-left')}</a></div></div></section>`}
function coaches(){const n=D.coaches.length;return `${pageHero('Meet the coaches','Get to know the people who guide each session.')}<section class="section-pad cr-section"><div class="container-fluid">${sectionIntro('Our team','Coaches who guide every length.','Choose a coach to see their focus, experience and approach.','center')}<div class="cr-stage" id="crStage">
<div class="cr-roster" role="tablist" aria-label="Our coaches" aria-orientation="vertical"><span class="cr-roster-bar" aria-hidden="true"></span>${D.coaches.map((c,k)=>`<button type="button" class="cr-pick${k===0?' active':''}" role="tab" id="crTab${k}" aria-controls="crPanel${k}" aria-selected="${k===0}" tabindex="${k===0?0:-1}" data-i="${k}"><span class="cr-no">${String(k+1).padStart(2,'0')}</span><span class="cr-pick-text"><strong>${c.name}</strong><small>${c.role}</small></span><span class="cr-pick-arrow" aria-hidden="true">${icon('arrow-up-right')}</span></button>`).join('')}</div>
<div class="cr-panels">${D.coaches.map((c,k)=>`<article class="cr-panel${k===0?' active':''}" role="tabpanel" id="crPanel${k}" aria-labelledby="crTab${k}" ${k===0?'':'data-idle'}><figure class="cr-photo"><img loading="lazy" src="${c.img}" alt="${c.name}, ${c.role}"><figcaption>${String(k+1).padStart(2,'0')} / ${String(n).padStart(2,'0')}</figcaption></figure><div class="cr-info"><span class="cr-spec">${c.specialty}</span><h2>${c.name}</h2><p class="cr-role">${c.role}</p><span class="cr-exp">${icon('award')}${c.experience}</span><p class="cr-bio">${c.bio}</p><div class="cr-actions"><a class="btn-aqua" href="${PG}coach-details.html?coach=${encodeURIComponent(c.name)}">Coach profile ${icon('arrow-up-right')}</a><a class="text-link" href="${PG}book-now.html">Book a trial</a></div></div></article>`).join('')}</div>
</div></div></section><section class="section-pad ch-standards"><div class="container-fluid"><div class="ch-grid"><div class="ch-intro"><span class="eyebrow">Coaching standards</span><h2 class="section-title">What you can expect from every coach.</h2><p class="section-copy">Whatever the programme or age group, our coaches share the same commitments, so every swimmer gets a consistent, supportive experience.</p><div class="ch-actions"><a class="btn-primary-custom" href="${PG}book-now.html">Book a trial ${icon('arrow-up-right')}</a><a class="text-link" href="${PG}batch-timings.html">View batch timings</a></div></div><div class="ch-cards"><article class="ch-card"><span class="ch-icon">${icon('message-circle')}</span><h3>Clear instruction</h3><p>One focus per session, explained step by step and shown with a demonstration.</p></article><article class="ch-card"><span class="ch-icon">${icon('shield-check')}</span><h3>Safety awareness</h3><p>Pool rules, supervision and water awareness are part of every lesson.</p></article><article class="ch-card"><span class="ch-icon">${icon('target')}</span><h3>Personal goals</h3><p>Targets are matched to each swimmer’s level, pace and ambitions.</p></article><article class="ch-card"><span class="ch-icon">${icon('clipboard-check')}</span><h3>Regular feedback</h3><p>Swimmers and parents hear what is going well and what to practise next.</p></article></div></div></div></section>`}
function batchTimings(){const days=['Monday','Tuesday','Wednesday','Thursday','Friday','Saturday','Sunday'];const total=8;return `${pageHero('Find a batch that fits your week','Browse the weekly timetable by day, age group or programme.')}<section class="section-pad bt-section"><div class="container-fluid"><div class="bt-wrap">
<div class="bt-tabs" id="btTabs" role="tablist" aria-label="Filter by day"><span class="bt-tab-pill" aria-hidden="true"></span><button type="button" class="bt-tab active" data-day="all" role="tab" aria-selected="true">All days</button>${days.map(d=>`<button type="button" class="bt-tab" data-day="${d}" role="tab" aria-selected="false"><span class="bt-tab-long">${d}</span><span class="bt-tab-short">${d.slice(0,3)}</span></button>`).join('')}</div>
<div class="bt-filters"><label class="bt-field"><span>Age group</span><select class="form-select" id="batchGroup"><option value="all">All age groups</option><option>Kids</option><option>Teens</option><option>Adults</option></select></label><label class="bt-field"><span>Programme</span><select class="form-select" id="batchProgram"><option value="all">All programmes</option>${D.programs.map(p=>`<option>${p.title}</option>`).join('')}</select></label><label class="bt-field"><span>Coach</span><select class="form-select" id="batchCoach"><option value="all">All coaches</option>${D.coaches.map(c=>`<option>${c.name}</option>`).join('')}</select></label><button type="button" class="bt-reset" id="btReset">Reset</button></div>
<div class="bt-meta"><span id="btCount" aria-live="polite">${D.batches.length} batches</span><span class="bt-legend"><i class="dot ok"></i>Available<i class="dot low"></i>Limited<i class="dot full"></i>Full</span></div>
<div class="bt-head" aria-hidden="true"><span>Day</span><span>Time</span><span>Programme &amp; coach</span><span>Group</span><span>Seats</span><span></span></div>
<ol id="batchCards" class="bt-list">${D.batches.map((b,i)=>{const s=b.status.toLowerCase();const cls=s==='available'?'ok':s==='limited'?'low':'full';const full=b.status==='Full';const [from,to]=b.time.split(/\s*[–-]\s*/);return `<li class="bt-row batch-item ${cls}" style="--i:${i};--fill:${Math.min(100,Math.round(b.seats/total*100))}%" data-day="${b.day}" data-group="${b.group}" data-program="${b.program}" data-coach="${b.coach}"><span class="bt-day"><b>${b.day}</b></span><span class="bt-time"><b>${from}</b><em>to ${to||''}</em></span><span class="bt-main"><strong>${b.program}</strong><small>with ${b.coach}</small></span><span class="bt-group">${b.group}</span><span class="bt-seats"><span class="bt-meter"><i></i></span><small><b>${b.seats}</b> seats · ${b.status}</small></span><a class="bt-go ${full?'disabled':''}" href="${PG}book-now.html" ${full?'aria-disabled="true" tabindex="-1"':''}>${full?'Full':'Choose'} ${icon('arrow-up-right')}</a></li>`}).join('')}</ol>
<div class="bt-empty" id="btEmpty" hidden><strong>No batches match those filters.</strong><span>Try another day or reset the filters.</span></div>
<p class="form-note mt-4">Availability shown is indicative. Final batch places are confirmed by the academy team.</p></div></div></section>`}
function booking(){return `${pageHero('Book a trial or request enrolment','Tell us about the swimmer and preferred programme. Submitting this form does not reserve a seat or take payment.')}<section class="section-pad"><div class="container-fluid"><div class="row g-4"><div class="col-lg-8"><form id="bookingForm" class="content-card"><div class="booking-progress" id="bookingProgress">${Array.from({length:8},(_,i)=>`<span class="${i===0?'active':''}"></span>`).join('')}</div><div class="d-flex justify-content-between align-items-center mb-4"><div><span class="eyebrow" id="bookingStepLabel">Step 1 of 8</span><h2 class="h3 mt-2" id="bookingStepTitle">Who is swimming?</h2></div><small class="form-note">Required fields are marked *</small></div>
<div class="booking-step active" data-step="0"><div class="row g-3"><div class="col-md-8"><label class="form-label">Swimmer category *</label><select class="form-select" name="category" required><option value="">Choose category</option><option>Kids</option><option>Teens</option><option>Adults</option></select></div><div class="col-12"><p class="form-note">Choose the age group that best describes the swimmer. A coach can help confirm the best programme after reviewing their experience.</p></div><div class="col-12"><div class="category-picks" id="categoryPicks"><button type="button" class="category-pick" data-cat="Kids"><span class="cp-age">Ages 4–12</span><strong>Kids</strong><small>Water confidence, floating and first strokes in small, playful groups.</small></button><button type="button" class="category-pick" data-cat="Teens"><span class="cp-age">Ages 13–17</span><strong>Teens</strong><small>Stroke technique, stamina and safe, confident swimming habits.</small></button><button type="button" class="category-pick" data-cat="Adults"><span class="cp-age">Ages 18+</span><strong>Adults</strong><small>Beginner-friendly lessons, fitness swimming and fear-free water learning.</small></button></div></div><div class="col-12"><div class="category-tip"><strong>Not sure which fits?</strong><span>Pick the closest option. Our coaches will confirm the right level and batch with you before anything is final.</span></div></div></div></div>
<div class="booking-step" data-step="1"><div class="row g-3"><div class="col-md-6"><label class="form-label">Swimmer name *</label><input class="form-control" name="swimmer" required placeholder="Full name"></div><div class="col-md-6"><label class="form-label">Date of birth *</label><input class="form-control" name="dob" type="date" required></div><div class="col-md-6"><label class="form-label">Gender (optional)</label><select class="form-select" name="gender"><option value="">Prefer not to say</option><option>Female</option><option>Male</option><option>Non-binary</option><option>Self describe</option></select></div><div class="col-md-6"><label class="form-label">Current swimming experience</label><select class="form-select" name="experience"><option>New to swimming</option><option>Some water confidence</option><option>Can swim short distances</option><option>Confident swimmer</option></select></div><div class="col-12"><label class="form-label">Parent / guardian name (required for minors)</label><input class="form-control" name="guardian" placeholder="Parent or guardian"></div></div></div>
<div class="booking-step" data-step="2"><div class="row g-3"><div class="col-md-6"><label class="form-label">Programme *</label><select class="form-select" id="bookingProgram" name="program" required><option value="">Choose programme</option>${D.programs.map(p=>`<option value="${p.title}">${p.title}</option>`).join('')}</select></div><div class="col-md-6"><label class="form-label">Skill level *</label><select class="form-select" name="level" required><option value="">Choose level</option><option>Beginner</option><option>Intermediate</option><option>Advanced</option><option>Competitive</option><option>Not sure yet</option></select></div><div class="col-12"><label class="form-label">What would you like to work towards?</label><textarea class="form-control" rows="4" name="goals" placeholder="Share any learning goals or helpful context"></textarea></div></div></div>
<div class="booking-step" data-step="3"><div class="row g-3"><div class="col-12"><label class="form-label">Preferred batch *</label><select class="form-select" name="batch" required><option value="">Choose a batch</option>${D.batches.filter(b=>b.status!=='Full').map(b=>`<option value="${b.day} · ${b.time} · ${b.program} · ${b.coach}">${b.day} · ${b.time} — ${b.program} with ${b.coach} (${b.seats} seats)</option>`).join('')}</select></div><div class="col-md-6"><label class="form-label">Preferred coach</label><select class="form-select" name="coach"><option>Any available coach</option>${D.coaches.map(c=>`<option>${c.name}</option>`).join('')}</select></div><div class="col-md-6"><label class="form-label">Pool / facility preference</label><select class="form-select" name="facility"><option>Main pool</option><option>Training pool (if available)</option><option>Discuss with academy</option></select></div></div></div>
<div class="booking-step" data-step="4"><div class="row g-3"><div class="col-md-6"><label class="form-label">Preferred start date *</label><input type="date" class="form-control" name="startDate" required></div><div class="col-md-6"><label class="form-label">Session frequency *</label><select class="form-select" name="frequency" required><option value="">Choose frequency</option><option>Once a week</option><option>Twice a week</option><option>Three times a week</option><option>Flexible / discuss with team</option></select></div><div class="col-12"><label class="form-label">Preferred days (optional)</label><input class="form-control" name="preferredDays" placeholder="e.g. Monday and Thursday"></div></div></div>
<div class="booking-step" data-step="5"><div class="row g-3"><div class="col-md-6"><label class="form-label">Contact name *</label><input class="form-control" name="contact" required placeholder="Your name"></div><div class="col-md-6"><label class="form-label">Email address *</label><input class="form-control" type="email" name="email" required placeholder="you@example.com"></div><div class="col-md-6"><label class="form-label">Phone number *</label><input class="form-control" name="phone" required placeholder="Phone number"></div><div class="col-md-6"><label class="form-label">Emergency contact</label><input class="form-control" name="emergency" placeholder="Optional contact number"></div><div class="col-12"><label class="form-label">Address</label><textarea class="form-control" name="address" rows="2" placeholder="Street, city and postal code"></textarea></div><div class="col-12"><label class="form-label">Additional information</label><textarea class="form-control" name="notes" rows="3" placeholder="Anything the team should know?"></textarea></div></div></div>
<div class="booking-step" data-step="6"><div class="booking-review"><span class="eyebrow">Fee summary</span><h3 class="h5 mt-2">Review the programme cost.</h3><div id="feeBreakdown" class="mt-3"></div><div class="mt-4"><label class="form-label">Preferred payment method</label><select class="form-select" name="paymentMethod"><option>Discuss with academy</option><option>Card</option><option>Bank transfer</option><option>Other (confirm with academy)</option></select></div></div></div>
<div class="booking-step" data-step="7"><div class="booking-review"><h3 class="h5">Review your request</h3><div id="bookingReview" class="small"></div><p class="form-note mt-3">Your request is saved in this browser only. It is not a confirmed reservation, enrolment, invoice or payment.</p><div class="form-check mt-3"><input class="form-check-input" type="checkbox" id="bookingTerms" required><label class="form-check-label small" for="bookingTerms">I agree that the academy may contact me about this enquiry.</label></div></div></div>
<div class="d-flex justify-content-between mt-4"><button type="button" class="btn-outline-custom" id="bookingBack" disabled>Back</button><button type="button" class="btn-primary-custom" id="bookingNext">Continue ${icon('arrow-right')}</button><button type="submit" class="btn-primary-custom d-none" id="bookingSubmit">Send request ${icon('send')}</button></div></form></div><div class="col-lg-4"><div class="soft-panel"><span class="eyebrow">What happens next</span><h3 class="mt-3">A simple first conversation.</h3><div class="member-list mt-4"><div class="member-list-item"><span class="list-icon">${icon('clipboard-list')}</span><div><strong>Share your preferences</strong><small>Tell us who is swimming and what they hope to learn.</small></div></div><div class="member-list-item"><span class="list-icon">${icon('message-circle')}</span><div><strong>Talk with the team</strong><small>Confirm suitability, schedule and facility details.</small></div></div><div class="member-list-item"><span class="list-icon">${icon('calendar-check')}</span><div><strong>Confirm next steps</strong><small>Final booking is handled after staff confirmation.</small></div></div></div></div><div class="content-card mt-3"><span class="eyebrow">Questions?</span><h3 class="mt-3">Need help choosing?</h3><p>Contact the academy and ask about programme levels or trial sessions.</p><a href="${PG}contact.html" class="text-link">Contact us ${icon('arrow-up-right')}</a></div></div></div></div></section>`}
function confirmation(){let req=JSON.parse(localStorage.getItem('wavecrestLastBooking')||'null');return `${pageHero('Thanks — your request is recorded','This confirmation is generated in your browser. It is not a confirmed class booking, payment receipt or email confirmation.')}<section class="section-pad"><div class="container-fluid"><div class="content-card text-center mx-auto" style="max-width:760px;padding:55px"><div class="trust-icon mx-auto" style="width:70px;height:70px;border-radius:50%">${icon('check')}</div><span class="eyebrow mt-4">Request received</span><h2 class="section-title mx-auto">Your next step starts with a conversation.</h2><p class="section-copy mx-auto">Thank you. Our team will review your details and get in touch to confirm the next step.</p><div id="confirmationDetails" class="booking-review text-start mt-4">${req?`<strong>${req.swimmer||'Swimmer'}</strong><br>${req.program||'Programme to be discussed'}<br>${req.batch||'Batch to be confirmed'}<br>${req.email||''}`:'No request details found in local browser storage.'}</div><a href="${ROOT}index.html" class="btn-primary-custom mt-4">Return home ${icon('arrow-up-right')}</a></div></div></section>`}
function facilities(){const spaces=[['Main pool','Editable facility description and dimensions.'],['Training space','Describe shallow-water or learner areas, if available.'],['Changing facilities','List available changing and shower facilities.'],['Visitor areas','Explain viewing or seating arrangements.']];const care=[['droplets','Water care','Insert verified water testing and maintenance information, including the academy’s.'],['life-buoy','Safety equipment','List the equipment, staff procedures and pool rules that actually apply at your facility.'],['accessibility','Getting around','Describe access, parking, arrival instructions and any accessibility provisions.']];return `${pageHero('Spaces made for learning','Explore our pool and the spaces that make every visit comfortable.')}
<section class="section-pad fc-section"><div class="container-fluid"><div class="fc-wrap">
${sectionIntro('The pool environment','A clear, calm space to focus on the water.','Lane availability, supervision and accessibility details are shared by the academy team on request.','center')}
<div class="fc-split fc-reveal"><figure class="fc-photo"><img loading="lazy" src="${ROOT}assets/images/facilities/indoor-pool.jpg" alt="Indoor swimming pool with clear water"><figcaption><span>${icon('waves')}</span>Indoor pool</figcaption></figure>
<ol class="fc-spaces">${spaces.map((s,k)=>`<li style="--d:${k*90}ms"><span class="fc-no">${String(k+1).padStart(2,'0')}</span><div><strong>${s[0]}</strong><p>${s[1]}</p></div><span class="fc-arrow" aria-hidden="true">${icon('arrow-up-right')}</span></li>`).join('')}</ol></div>
<div class="fc-care fc-reveal">${care.map((c,k)=>`<article style="--d:${k*110}ms"><span class="fc-ico">${icon(c[0])}</span><h3>${c[1]}</h3><p>${c[2]}</p></article>`).join('')}</div>
<div class="fc-visit fc-reveal"><article style="--d:0ms"><span class="eyebrow">Hours</span><h3>Plan your visit</h3><p>Monday–Saturday · 7:00 AM–7:00 PM. We are open every day so visit us whenever you free.</p></article><article style="--d:110ms"><span class="eyebrow">Location</span><h3>Find the academy</h3><p>Add the verified street address, arrival instructions and transport information  provisions.</p><a href="${PG}contact.html" class="text-link">Contact details ${icon('arrow-up-right')}</a></article><article style="--d:220ms"><span class="eyebrow">Visitor information</span><h3>Before you arrive</h3><p>Explain check-in, changing facilities, spectator access and any required swim equipment.</p></article></div>
</div></div></section>`}
function gallery(){const U=id=>`${ROOT}assets/images/${id}.jpg`;let imgs=[{t:'Pool spaces',c:'pool',cl:'Pool spaces',img:U('facilities/indoor-pool'),d:'A bright indoor pool with clearly marked lanes, a gentle shallow end and clean deck space for lessons and practice.',m:[['Area','Main teaching pool'],['Best for','Beginners and families'],['Depth','Shallow to deep lanes']]},{t:'Swimming practice',c:'training',cl:'Training',img:U('gallery/swimming-practice'),d:'Coach-guided practice where swimmers repeat stroke fundamentals in small, supportive groups until each skill feels natural.',m:[['Session','Stroke technique'],['Best for','Teens and improvers'],['Group size','Small batches']]},{t:'Poolside learning',c:'people',cl:'People',img:U('gallery/poolside-learning'),d:'Friendly poolside moments where coaches explain each step, answer questions and keep every swimmer comfortable.',m:[['Focus','Water confidence'],['Best for','Kids and first-timers'],['Support','Coach on the deck']]},{t:'Training sessions',c:'training',cl:'Training',img:U('gallery/training-sessions'),d:'Structured training blocks that build endurance, breathing rhythm and efficient technique one length at a time.',m:[['Session','Endurance sets'],['Best for','Regular swimmers'],['Goal','Stronger, smoother laps']]},{t:'Performance pool',c:'pool',cl:'Pool spaces',img:U('facilities/performance-pool'),d:'A competition-style pool used for speed work, pacing practice and performance pathway sessions.',m:[['Area','Performance lanes'],['Best for','Advanced swimmers'],['Use','Speed and pacing']]},{t:'Water confidence',c:'people',cl:'People',img:U('gallery/water-confidence'),d:'The very first steps in the water: floating, breathing and moving freely, with patient guidance at every stage.',m:[['Focus','First splash skills'],['Best for','All ages'],['Pace','Set by the swimmer']]}];window.__gallery=imgs;return `${pageHero('A look inside the swimming journey','Explore life at the academy, from first splashes to focused training.')}<section class="section-pad gallery-page"><div class="container-fluid">${sectionIntro('Inside the academy','Moments from the pool and beyond','Browse our pool spaces, training sessions and the people who make every lesson feel welcome.','center')}<div class="gallery-head"><div class="filter-bar gallery-tabs" id="galleryFilters"><button class="filter-chip active" data-filter="all">All moments <sup>${imgs.length}</sup></button><button class="filter-chip" data-filter="pool">Pool spaces <sup>${imgs.filter(x=>x.c==='pool').length}</sup></button><button class="filter-chip" data-filter="training">Training <sup>${imgs.filter(x=>x.c==='training').length}</sup></button><button class="filter-chip" data-filter="people">People <sup>${imgs.filter(x=>x.c==='people').length}</sup></button></div><div class="gallery-select"><label class="visually-hidden" for="galleryFilterSelect">Filter gallery</label><select id="galleryFilterSelect" aria-label="Filter gallery"><option value="all">All moments (${imgs.length})</option><option value="pool">Pool spaces (${imgs.filter(x=>x.c==='pool').length})</option><option value="training">Training (${imgs.filter(x=>x.c==='training').length})</option><option value="people">People (${imgs.filter(x=>x.c==='people').length})</option></select></div><span class="gallery-hint">Select any photo to see its details</span></div><div class="gm-mosaic" id="galleryMosaic">${imgs.map((im,i)=>`<button type="button" class="gallery-item gm-tile" data-category="${im.c}" data-gallery-open="${i}" aria-label="View details: ${im.t}"><img src="${im.img}" alt="${im.t}" loading="lazy"><span class="gm-tile-shade"></span><span class="gm-tile-no">${String(i+1).padStart(2,'0')}</span><span class="gm-tile-go">${icon('arrow-up-right')}</span><span class="gm-tile-cap"><span class="gm-tile-tag">${im.cl}</span><strong>${im.t}</strong></span></button>`).join('')}</div></div></div></section><div class="gallery-modal" id="galleryModal" role="dialog" aria-modal="true" aria-labelledby="gmTitle" hidden><div class="gallery-modal-panel"><button type="button" class="gm-close" id="gmClose" aria-label="Close details">${icon('x')}</button><div class="gm-media"><img id="gmImage" src="" alt=""></div><div class="gm-info"><span class="gm-tag" id="gmTag"></span><h2 id="gmTitle"></h2><p id="gmText"></p><dl class="gm-meta" id="gmMeta"></dl><div class="gm-actions"><button type="button" class="gm-nav" id="gmPrev">${icon('arrow-left')} Previous</button><span class="gm-count" id="gmCount"></span><button type="button" class="gm-nav" id="gmNext">Next ${icon('arrow-right')}</button></div><a class="btn-primary-custom gm-cta" href="${PG}book-now.html">Book a trial session ${icon('arrow-up-right')}</a></div></div></div>`}
function pricing(){return `${pageHero('Simple ways to get started','Clear fees for every programme and membership option.')}<section class="section-pad"><div class="container-fluid"><div class="row g-4"><div class="col-md-4"><div class="content-card"><span class="eyebrow">Group learning</span><h3 class="mt-3">Kids & Teens</h3><div class="display-font" style="font-size:38px;font-weight:800;margin:20px 0">$180<small style="font:500 12px Inter;color:var(--muted)"> / programme</small></div><p>Structured group sessions, skill milestones and coach feedback.</p><hr style="border-color:var(--line)"><p>✓ Age-aware lesson pathway<br>✓ Weekly practice schedule<br>✓ Progress review points</p><a href="${PG}book-now.html" class="btn-primary-custom w-100">Enquire about this plan</a></div></div><div class="col-md-4"><div class="content-card" style="border:2px solid var(--aqua)"><span class="eyebrow">Adult learning</span><h3 class="mt-3">Adult Foundations</h3><div class="display-font" style="font-size:38px;font-weight:800;margin:20px 0">$195<small style="font:500 12px Inter;color:var(--muted)"> / programme</small></div><p>Supportive instruction for water confidence and foundational technique.</p><hr style="border-color:var(--line)"><p>✓ Beginner-friendly structure<br>✓ Clear learning objectives<br>✓ Coach-led feedback</p><a href="${PG}book-now.html" class="btn-primary-custom w-100">Enquire about this plan</a></div></div><div class="col-md-4"><div class="content-card"><span class="eyebrow">Performance focus</span><h3 class="mt-3">Performance Squad</h3><div class="display-font" style="font-size:38px;font-weight:800;margin:20px 0">$290<small style="font:500 12px Inter;color:var(--muted)"> / programme</small></div><p>Purposeful practice for swimmers developing efficient, repeatable technique.</p><hr style="border-color:var(--line)"><p>✓ Structured squad sessions<br>✓ Technique refinement<br>✓ Training feedback</p><a href="${PG}book-now.html" class="btn-primary-custom w-100">Enquire about this plan</a></div></div></div><div class="soft-panel mt-5"><h3>What is included?</h3><p>Pricing and inclusions vary by programme. Add registration charges, private lesson fees, make-up policies, cancellation terms and payment due dates only after the academy confirms them.</p></div></div></section>`}
function blog(){return `${pageHero('Ideas for the time you spend in the water','Practical articles on swimming fundamentals, water awareness, technique and the learning journey.')}<section class="section-pad"><div class="container-fluid"><div class="d-flex gap-2 flex-wrap align-items-center mb-4"><input id="blogSearch" class="form-control" style="max-width:320px" placeholder="Search articles"><select class="form-select" id="blogCategory" style="max-width:190px"><option value="all">All categories</option><option>Beginner Guides</option><option>Technique</option><option>Water Safety</option></select></div><div class="row g-4" id="blogGrid">${D.articles.map((a,i)=>`<div class="col-md-6 col-lg-4 blog-item" data-index="${i}" data-category="${a.category}" data-search="${a.title.toLowerCase()} ${a.desc.toLowerCase()}"><article class="content-card p-0 overflow-hidden"><img src="${a.img}" alt="${a.title}" style="height:230px;width:100%;object-fit:cover" loading="lazy"><div class="p-4"><small class="eyebrow">${a.category}</small><p class="mt-2 mb-2" style="font-size:10px">${a.date} · ${a.read}</p><h3>${a.title}</h3><p>${a.desc}</p><a class="text-link" href="${PG}blog-details.html">Read article ${icon('arrow-up-right')}</a></div></article></div>`).join('')}</div><div class="text-center mt-5"><button class="btn-outline-custom" id="loadMoreArticles">Load more articles ${icon('arrow-down')}</button></div></div></section>`}
function blogDetails(){return `${pageHero('A confident first lesson starts before the water','Begin with simple preparation, a clear plan and a pace that feels manageable.')}<section class="section-pad"><div class="container-fluid"><div class="row g-5"><article class="col-lg-8"><img src="${ROOT}assets/images/blog/confident-first-lesson.jpg" alt="Swimming pool" style="width:100%;height:440px;object-fit:cover;border-radius:22px"><div class="d-flex gap-3 my-4"><small>12 Nov 2026</small><small>·</small><small>4 min read</small><small>·</small><small>Beginner Guides</small></div><h2 class="section-title">Preparation can make the first visit feel easier.</h2><p>For a new swimmer, the first lesson is an opportunity to understand the pool environment, meet the coach and begin with manageable skills. Arriving a little early can give everyone time to find the changing area, ask questions and understand the session routine.</p><h3 class="h4 mt-4">Pack the essentials</h3><p>Bring suitable swimwear, a towel and any equipment the academy has requested. Check the facility’s own guidance for footwear, changing arrangements and poolside rules.</p><h3 class="h4 mt-4">Share useful context</h3><p>Let the coach know if the swimmer is new to the water, has previous experience or has a particular goal. That context can help the coach choose an appropriate starting point.</p><h3 class="h4 mt-4">Keep progress gradual</h3><p>Comfort and technique grow through practice. Focus on one or two clear cues rather than expecting every skill to develop in one session.</p><div class="soft-panel mt-5"><strong>Safety reminder</strong><p class="mb-0">Swimming lessons do not replace active supervision. Children should be closely supervised by a responsible adult in and around water.</p></div></article><aside class="col-lg-4"><div class="content-card"><h3>More from the journal</h3>${D.articles.slice(1).map(a=>`<div class="d-flex gap-3 py-3" style="border-bottom:1px solid var(--line)"><img src="${a.img}" alt="" style="width:80px;height:70px;object-fit:cover;border-radius:10px"><div><strong style="font:600 12px Sora">${a.title}</strong><small class="d-block mt-1" style="color:var(--muted)">${a.category}</small></div></div>`).join('')}</div></aside></div></div></section>`}
function contact(){return `${pageHero('Let’s find the right next step','Ask about programmes, trial sessions, batch options or facilities.')}<section class="section-pad"><div class="container-fluid"><div class="row g-4"><div class="col-lg-7"><form class="content-card needs-validation" data-demo-form="contact" novalidate><h2 class="h3 mb-4">Send an enquiry</h2><div class="row g-3"><div class="col-md-6"><label class="form-label">Full name *</label><input class="form-control" required placeholder="Your name"></div><div class="col-md-6"><label class="form-label">Email address *</label><input type="email" class="form-control" required placeholder="you@example.com"></div><div class="col-md-6"><label class="form-label">Phone number</label><input class="form-control" placeholder="Phone number"></div><div class="col-md-6"><label class="form-label">Swimmer category</label><select class="form-select"><option>Choose category</option><option>Kids</option><option>Teens</option><option>Adults</option></select></div><div class="col-md-6"><label class="form-label">Programme of interest</label><select class="form-select"><option>Not sure yet</option>${D.programs.map(p=>`<option>${p.title}</option>`).join('')}</select></div><div class="col-md-6"><label class="form-label">Subject</label><input class="form-control" placeholder="How can we help?"></div><div class="col-12"><label class="form-label">Message *</label><textarea class="form-control" rows="5" required placeholder="Tell us a little about your enquiry"></textarea></div><div class="col-12 contact-submit"><button class="btn-primary-custom" type="submit">Send enquiry ${icon('send')}</button><p class="form-note mt-2">Your details are not sent anywhere from this form yet.</p></div></div></form></div><div class="col-lg-5"><div class="soft-panel h-100"><span class="eyebrow">Contact the academy</span><h3 class="mt-3">We’re happy to help you get started.</h3><div class="member-list mt-4"><div class="member-list-item"><span class="list-icon">${icon('map-pin')}</span><div><strong>Academy address</strong><small>Los Angeles, CA, USA.</small></div></div><div class="member-list-item"><span class="list-icon">${icon('phone')}</span><div><strong>Call the team</strong><small>+1 (567) 321-8855</small></div></div><div class="member-list-item"><span class="list-icon">${icon('mail')}</span><div><strong>Email</strong><small>wavecrest@gmail.com</small></div></div><div class="member-list-item"><span class="list-icon">${icon('clock')}</span><div><strong>Business hours</strong><small>Mon–Sat · 7:00 AM–7:00 PM</small></div></div></div><div class="contact-first"><h4>Planning your first visit?</h4><ul><li>${icon('circle-check')}<span>Arrive about 10 minutes early so the swimmer can settle in and meet the coach.</span></li><li>${icon('circle-check')}<span>Bring swimwear, a towel and goggles, and let us know if you need a swim cap.</span></li><li>${icon('circle-check')}<span>Share the swimmer’s experience level so we can suggest the right batch.</span></li></ul></div><div class="d-flex gap-2 flex-wrap contact-social"><button type="button" class="btn-outline-custom" id="whatsappPlaceholder">WhatsApp contact ${icon('message-circle')}</button><a class="btn-outline-custom" href="https://www.instagram.com/">Instagram ${icon('external-link')}</a></div></div></div></div></div></section><section class="map-section" aria-label="Find us on the map"><div class="map-full"><iframe class="map-frame" title="Wavecrest Swimming Academy on Google Maps" src="https://www.google.com/maps/embed?pb=!1m18!1m12!1m3!1d423284.0444319843!2d-118.74139090464179!3d34.02060840261818!2m3!1f0!2f0!3f0!3m2!1i1024!2i768!4f13.1!3m3!1m2!1s0x80c2c75ddc27da13%3A0xe22fdf6f254608f4!2sLos%20Angeles%2C%20CA%2C%20USA!5e0!3m2!1sen!2sin!4v1795680868737!5m2!1sen!2sin" loading="lazy" referrerpolicy="no-referrer-when-downgrade" allowfullscreen></iframe><a class="map-directions" href="https://www.google.com/maps/search/?api=1&query=${encodeURIComponent(MAP_QUERY)}" target="_blank" rel="noopener">Get directions ${icon('arrow-up-right')}</a></div></section><section class="section-pad-sm"><div class="container-fluid"><span class="eyebrow">Quick answers</span><h2 class="section-title">A few helpful things to know.</h2><div class="row g-3"><div class="col-md-4"><details class="content-card"><summary><strong>How do I choose a programme?</strong></summary><p class="mt-3 mb-0">Share the swimmer’s age, experience and goals. The coaching team can help confirm a suitable starting point.</p></details></div><div class="col-md-4"><details class="content-card"><summary><strong>Can I request a trial session?</strong></summary><p class="mt-3 mb-0">Use the Book Now form to share your preferences. A real trial booking needs staff confirmation.</p></details></div><div class="col-md-4"><details class="content-card"><summary><strong>How I confirm my batch timings?</strong></summary><p class="mt-3 mb-0">Pick your preferred day and time in the Book Now form. Our team will confirm availability and your final batch.</p></details></div></div></div></section>`}
function authPage(type){if(type==='login')return `<section class="section-pad auth-section"><div class="container-fluid"><form class="content-card mx-auto" style="max-width:500px" data-demo-form="login"><h2 class="h3">Sign in</h2><p class="login-sub">Choose how you are signing in, then enter your details.</p><fieldset class="login-role"><legend class="form-label">Sign in as</legend><div class="role-switch" id="loginRole"><label><input type="radio" name="role" value="member" checked><span>Member</span></label><label><input type="radio" name="role" value="admin"><span>Admin</span></label></div></fieldset><div class="mb-3"><label class="form-label">Email or registered phone</label><input class="form-control" required placeholder="Email address or phone"></div><div class="mb-3"><label class="form-label">Password</label><div class="input-group"><input class="form-control" type="password" id="loginPassword" required placeholder="Password"><button class="login-eye" type="button" aria-label="Show or hide password" data-toggle-password="loginPassword">${icon('eye')}</button></div></div><div class="login-row"><label class="small"><input type="checkbox" class="form-check-input me-1"> Remember me</label><a class="text-link" href="${PG}forgot-password.html">Forgot password?</a></div><button class="btn-primary-custom w-100" type="submit">Sign in ${icon('arrow-right')}</button><p class="text-center mt-4 mb-0">New to the academy? <a class="text-link" href="${PG}register.html">Create an account</a></p></form></div></section>`;
if(type==='register')return `${pageHero('Create your member account','Set up a profile to keep swimmer and parent or guardian details together.')}<section class="section-pad"><div class="container-fluid"><form class="content-card mx-auto" style="max-width:650px" data-demo-form="register"><h2 class="h3">Create account</h2><div class="row g-3 mt-2"><div class="col-md-6"><label class="form-label">Full name *</label><input class="form-control" required></div><div class="col-md-6"><label class="form-label">Email *</label><input type="email" class="form-control" required></div><div class="col-md-6"><label class="form-label">Phone *</label><input class="form-control" required></div><div class="col-md-6"><label class="form-label">Swimmer category</label><select class="form-select"><option>Adult</option><option>Kids</option><option>Teens</option></select></div><div class="col-md-6"><label class="form-label">Password *</label><input type="password" class="form-control" required minlength="8"></div><div class="col-md-6"><label class="form-label">Confirm password *</label><input type="password" class="form-control" required minlength="8"></div><div class="col-12"><label class="form-label">Parent / guardian details (for minors)</label><input class="form-control" placeholder="Parent or guardian name and contact"></div><div class="col-12"><label class="small"><input type="checkbox" class="form-check-input me-1" required> I accept the academy terms and privacy notice.</label></div><div class="col-12"><button class="btn-primary-custom w-100" type="submit">Create account ${icon('arrow-right')}</button></div></div><p class="text-center mt-4 mb-0">Already registered? <a class="text-link" href="${PG}login.html">Sign in</a></p></form></div></section>`;
return `${pageHero('Reset your password','Enter the registered email or phone number.')}<section class="section-pad"><div class="container-fluid"><form class="content-card mx-auto" style="max-width:470px" data-demo-form="forgot"><h2 class="h3">Password recovery</h2><label class="form-label mt-4">Email or registered phone</label><input class="form-control" required placeholder="Email or phone"><button class="btn-primary-custom w-100 mt-3" type="submit">Request reset ${icon('arrow-right')}</button><a class="text-link justify-content-center w-100 mt-3" href="${PG}login.html">Back to login</a></form></div></section>`}
function about(){return `${pageHero('An academy built around the swimmer','Our story, our mission and the teaching philosophy behind every lesson.')}<section class="section-pad"><div class="container-fluid"><div class="split-feature"><div class="feature-photo"><img src="${ROOT}assets/images/about/about-team-pool.jpg" alt="Swimmer practising in a pool"></div><div><span class="eyebrow">Our approach</span><h2 class="section-title">Swimming is a skill for life, and every journey is personal.</h2><p class="section-copy">Wavecrest is presented as a welcoming academy for swimmers at different stages. Our philosophy brings together clear instruction, patient coaching and steady skill development.</p><a href="${PG}programs.html" class="text-link">Explore our programmes ${icon('arrow-up-right')}</a></div></div><div class="row g-4 mt-5"><div class="col-md-6"><div class="content-card"><span class="eyebrow">Our mission</span><h3 class="mt-3">Make learning clear and encouraging.</h3><p>Help swimmers understand the fundamentals, practise with purpose and build confidence over time.</p></div></div><div class="col-md-6"><div class="content-card"><span class="eyebrow">Our vision</span><h3 class="mt-3">Keep the next step within reach.</h3><p>Create an environment where children, teens and adults can continue to learn at an appropriate pace.</p></div></div></div></div></section><section class="section-pad" style="background:var(--surface-soft)"><div class="container-fluid"><div class="row g-4"><div class="col-lg-5"><span class="eyebrow">Our story</span><h2 class="section-title">A learning space shaped around steady progress.</h2><p>Use this story area for the academy’s founding journey, local community role and verified milestones.</p></div><div class="col-lg-7"><div class="story-cards"><div class="content-card story-card"><span class="trust-icon">${icon('route')}</span><div><h3>Our training approach</h3><p>Sessions combine an achievable focus, coach demonstration, guided practice and feedback appropriate to the swimmer’s level.</p></div></div><div class="content-card story-card"><span class="trust-icon">${icon('shield-check')}</span><div><h3>Water safety awareness</h3><p>Pool rules, listening to instructions, awareness of the environment and age-appropriate water skills form part of the learning conversation.</p></div></div></div></div></div></div></section><section class="section-pad ab-people"><div class="container-fluid"><div class="d-flex justify-content-between align-items-end gap-3 flex-wrap"><div><span class="eyebrow">Our people</span><h2 class="section-title mb-0">Meet the coaches who guide the journey.</h2></div><a href="${PG}coaches.html" class="text-link">Explore coaches ${icon('arrow-up-right')}</a></div><div class="row g-3 mt-2 about-coaches">${D.coaches.slice(0,3).map(c=>`<div class="col-md-4">${coachCard(c)}</div>`).join('')}</div></div></section><section class="section-pad ab-values"><div class="container-fluid"><div class="ab-head ab-head-center"><span class="eyebrow">What guides us</span><h2 class="section-title">Values behind every lesson.</h2><p class="section-copy">Four simple principles shape how we teach, how we coach and how we welcome every swimmer to the pool.</p></div><div class="ab-values-grid"><article class="ab-value"><span class="ab-value-num">01</span><span class="ab-value-icon">${icon('heart-handshake')}</span><h3>Patience first</h3><p>Every swimmer learns at their own pace, and progress is celebrated at every size.</p></article><article class="ab-value"><span class="ab-value-num">02</span><span class="ab-value-icon">${icon('shield-check')}</span><h3>Safety always</h3><p>Pool rules, clear instructions and water awareness are part of every session.</p></article><article class="ab-value"><span class="ab-value-num">03</span><span class="ab-value-icon">${icon('users')}</span><h3>Inclusive by design</h3><p>Children, teens and adults are welcome, with programmes shaped for each stage.</p></article><article class="ab-value"><span class="ab-value-num">04</span><span class="ab-value-icon">${icon('trending-up')}</span><h3>Steady progress</h3><p>Small, achievable goals help swimmers build skill and confidence over time.</p></article></div></div></section><section class="section-pad ab-lesson"><div class="container-fluid"><div class="ab-head ab-head-center ab-head-full"><div><span class="eyebrow">Inside a session</span><h2 class="section-title">How a lesson flows.</h2></div><p class="section-copy">Each session follows a familiar rhythm, so swimmers always know what to expect and what comes next.</p></div><ol class="ab-steps"><li class="ab-step"><span class="ab-step-dot">1</span><h3>Welcome &amp; warm-up</h3><p>Settle in, review pool rules and get comfortable in the water.</p></li><li class="ab-step"><span class="ab-step-dot">2</span><h3>Focus skill</h3><p>The coach introduces one clear, achievable skill with a live.</p></li><li class="ab-step"><span class="ab-step-dot">3</span><h3>Guided practice</h3><p>Swimmers practise with purpose while the coach supports each.</p></li><li class="ab-step"><span class="ab-step-dot">4</span><h3>Feedback &amp; next step</h3><p>A short review of what went well and what to work on next time.</p></li></ol></div></section><section class="cta-band"><div><h2>Every swimmer has a place to begin.</h2><p>Explore programme options or talk with our team.</p></div><a class="btn-aqua" href="${PG}book-now.html">Book a trial ${icon('arrow-up-right')}</a></section>`}
function special(pageKey){if(pageKey==='404')return `${pageHero('This page has drifted out of lane','The page may have moved or the address may be incorrect.')}<section class="section-pad text-center"><div class="container-fluid"><h2 style="font:800 clamp(5rem,15vw,10rem) Sora;color:var(--aqua)">404</h2><a href="${ROOT}index.html" class="btn-primary-custom">Back to homepage ${icon('arrow-up-right')}</a></div></section>`;return `${pageHero('A fresh start is coming','This space is ready for academy announcements, seasonal programmes or an upcoming launch.')}<section class="section-pad text-center"><div class="container-fluid"><div class="content-card mx-auto" style="max-width:600px"><span class="eyebrow">Coming soon</span><h2 class="section-title mx-auto">Good things are taking shape.</h2><p>Share your email to receive updates when this page is ready.</p><form class="newsletter-form d-flex gap-2"><input type="email" class="form-control" required placeholder="Email address"><button class="btn-primary-custom">Notify me</button></form></div></div></section>`}
