function initForms(){$$('form[data-demo-form],.newsletter-form').forEach(f=>f.addEventListener('submit',e=>{e.preventDefault();if(!f.reportValidity())return;let type=f.dataset.demoForm||'newsletter';if(type==='booking')return;if(type==='login'){const role=((f.querySelector('input[name=role]:checked')||{}).value)==='admin'?'admin':'member';try{sessionStorage.setItem('wavecrestRole',role)}catch(_){}location.href=role==='admin'?PG+'admin-dashboard/index.html':PG+'member-dashboard/index.html';return}toast(type==='login'?'Please sign in with your member or admin details.':type==='register'?'Thanks — your account request has been received.':type==='forgot'?'Thanks — if the account exists, reset instructions will be sent.':type==='contact'?'Thanks — your enquiry has been received. We will be in touch soon.':'Thanks — you have been subscribed.');f.reset()}))}
function initProgramFilters(){let g=$('#programGroup'),l=$('#programLevel');if(!g||!l)return;function apply(){let q=new URLSearchParams(location.search).get('group');if(q&&g.value==='all')g.value=q;let visible=D.programs.filter(p=>(g.value==='all'||p.group===g.value)&&(l.value==='all'||p.level===l.value));$('#programGrid').innerHTML=visible.length?visible.map(programCard).join(''):'<div class="content-card"><h3>No matching programmes</h3><p>Try another age group or skill level.</p></div>';icons()}g.addEventListener('change',apply);l.addEventListener('change',apply);apply()}
function initBatches(){const list=$('#batchCards');if(!list)return;const tabs=$('#btTabs'),pill=tabs.querySelector('.bt-tab-pill'),group=$('#batchGroup'),prog=$('#batchProgram'),coach=$('#batchCoach'),count=$('#btCount'),empty=$('#btEmpty');let day='all';function movePill(){const a=tabs.querySelector('.bt-tab.active');if(!a)return;pill.style.width=a.offsetWidth+'px';pill.style.transform='translateX('+a.offsetLeft+'px)'}function apply(){let n=0;$$('.batch-item').forEach(el=>{const ok=(day==='all'||el.dataset.day===day)&&(group.value==='all'||el.dataset.group===group.value)&&(prog.value==='all'||el.dataset.program===prog.value)&&(coach.value==='all'||el.dataset.coach===coach.value);el.hidden=!ok;el.classList.remove('bt-in');if(ok){el.style.setProperty('--n',n++)}});void list.offsetWidth;$$('.batch-item').forEach(el=>{if(!el.hidden)el.classList.add('bt-in')});count.textContent=n+(n===1?' batch':' batches');empty.hidden=n>0}tabs.addEventListener('click',e=>{const b=e.target.closest('.bt-tab');if(!b)return;tabs.querySelectorAll('.bt-tab').forEach(t=>{t.classList.toggle('active',t===b);t.setAttribute('aria-selected',t===b)});day=b.dataset.day;movePill();apply()});[group,prog,coach].forEach(x=>x.addEventListener('change',apply));$('#btReset').addEventListener('click',()=>{group.value=prog.value=coach.value='all';day='all';tabs.querySelectorAll('.bt-tab').forEach((t,i)=>{t.classList.toggle('active',i===0);t.setAttribute('aria-selected',i===0)});movePill();apply()});window.addEventListener('resize',movePill);if(document.fonts&&document.fonts.ready)document.fonts.ready.then(movePill);movePill();apply()}
