function initCoaches(){const st=$('#crStage');if(!st)return;st.classList.add('ready');const picks=[...st.querySelectorAll('.cr-pick')],panels=[...st.querySelectorAll('.cr-panel')],bar=st.querySelector('.cr-roster-bar');function bars(){const a=st.querySelector('.cr-pick.active');if(!a)return;bar.style.height=a.offsetHeight+'px';bar.style.transform='translateY('+a.offsetTop+'px)'}function show(k,focus){picks.forEach((b,i)=>{b.classList.toggle('active',i===k);b.setAttribute('aria-selected',i===k);b.tabIndex=i===k?0:-1});panels.forEach((p,i)=>{const on=i===k;if(on){p.removeAttribute('data-idle');p.classList.remove('active');void p.offsetWidth;p.classList.add('active')}else{p.classList.remove('active');p.setAttribute('data-idle','')}});bars();if(focus)picks[k].focus();if(window.matchMedia('(max-width:991px)').matches)picks[k].scrollIntoView({block:'nearest',inline:'center',behavior:'smooth'})}picks.forEach((b,i)=>b.addEventListener('click',()=>show(i)));st.querySelector('.cr-roster').addEventListener('keydown',e=>{const cur=picks.findIndex(b=>b.classList.contains('active'));let nx=null;if(['ArrowDown','ArrowRight'].includes(e.key))nx=(cur+1)%picks.length;if(['ArrowUp','ArrowLeft'].includes(e.key))nx=(cur-1+picks.length)%picks.length;if(e.key==='Home')nx=0;if(e.key==='End')nx=picks.length-1;if(nx!==null){e.preventDefault();show(nx,true)}});window.addEventListener('resize',bars);if(document.fonts&&document.fonts.ready)document.fonts.ready.then(bars);bars()}
function initGallery(){const layoutMosaic=()=>{const v=$$('.gm-tile').filter(x=>x.style.display!=='none');const n=v.length,full=n-n%4;v.forEach((x,i)=>{x.classList.remove('gm-big','gm-wide','gm-full');if(i<full){const k=i%4;if(k===0)x.classList.add('gm-big');else if(k===3)x.classList.add('gm-wide')}else{const r=n-full,k=i-full;if(r===1)x.classList.add('gm-full');else if(r===2||(r===3&&k===0))x.classList.add('gm-wide')}})};layoutMosaic();let f=$('#galleryFilters');const fs=$('#galleryFilterSelect');if(fs){fs.addEventListener('change',()=>{const t=$$('[data-filter]',f).find(x=>x.dataset.filter===fs.value);t&&t.click()});f&&f.addEventListener('click',e=>{const b=e.target.closest('[data-filter]');if(b)fs.value=b.dataset.filter})}if(f)f.addEventListener('click',e=>{let b=e.target.closest('[data-filter]');if(!b)return;$$('[data-filter]',f).forEach(x=>x.classList.toggle('active',x===b));$$('.gallery-item').forEach(x=>x.style.display=b.dataset.filter==='all'||x.dataset.category===b.dataset.filter?'':'none');layoutMosaic()});$$('[data-lightbox]').forEach(b=>b.addEventListener('click',()=>{$('#lightboxImage').src=b.dataset.lightbox;$('#lightbox').classList.add('show')}));$('#lightboxClose')?.addEventListener('click',()=>$('#lightbox').classList.remove('show'));$('#lightbox')?.addEventListener('click',e=>{if(e.target.id==='lightbox')e.currentTarget.classList.remove('show')});const gm=$('#galleryModal');if(!gm||!window.__gallery)return;const data=window.__gallery;let cur=0,lastFocus=null;const visible=()=>$$('.gallery-item').filter(x=>x.style.display!=='none').map(x=>+x.dataset.galleryOpen);const show=i=>{cur=i;const g=data[i];$('#gmImage').src=g.img;$('#gmImage').alt=g.t;$('#gmTag').textContent=g.cl;$('#gmTitle').textContent=g.t;$('#gmText').textContent=g.d;$('#gmMeta').innerHTML=g.m.map(m=>`<div><dt>${m[0]}</dt><dd>${m[1]}</dd></div>`).join('');const v=visible(),pos=v.indexOf(i);$('#gmCount').textContent=(pos+1)+' / '+v.length;gm.querySelector('.gm-info').scrollTop=0};const step=d=>{const v=visible();if(!v.length)return;let pos=v.indexOf(cur);pos=(pos+d+v.length)%v.length;show(v[pos])};const open=i=>{lastFocus=document.activeElement;show(i);gm.hidden=false;requestAnimationFrame(()=>gm.classList.add('show'));document.body.classList.add('gm-lock');$('#gmClose').focus()};const close=()=>{gm.classList.remove('show');document.body.classList.remove('gm-lock');setTimeout(()=>{gm.hidden=true},250);lastFocus&&lastFocus.focus&&lastFocus.focus()};$$('[data-gallery-open]').forEach(b=>b.addEventListener('click',()=>open(+b.dataset.galleryOpen)));$('#gmClose').addEventListener('click',close);gm.addEventListener('click',e=>{if(e.target===gm)close()});$('#gmPrev').addEventListener('click',()=>step(-1));$('#gmNext').addEventListener('click',()=>step(1));document.addEventListener('keydown',e=>{if(gm.hidden)return;if(e.key==='Escape')close();else if(e.key==='ArrowRight')step(1);else if(e.key==='ArrowLeft')step(-1)})}
function initBlog(){let s=$('#blogSearch'),c=$('#blogCategory');if(!s)return;let visibleCount=3;function apply(){let q=s.value.toLowerCase();$$('.blog-item').forEach(x=>x.style.display=(Number(x.dataset.index)<visibleCount)&&(x.dataset.search.includes(q))&&(c.value==='all'||x.dataset.category===c.value)?'':'none');let more=$('#loadMoreArticles');if(more)more.style.display=visibleCount>=D.articles.length?'none':''}s.addEventListener('input',apply);c.addEventListener('change',apply);$('#loadMoreArticles')?.addEventListener('click',()=>{visibleCount+=3;apply()});apply()}
function initBooking(){let form=$('#bookingForm');if(!form)return;let picks=$('#categoryPicks');if(picks){let sel=form.elements.category;let sync=()=>$$('.category-pick',picks).forEach(b=>b.classList.toggle('active',b.dataset.cat===sel.value));picks.addEventListener('click',e=>{let b=e.target.closest('.category-pick');if(!b)return;sel.value=b.dataset.cat;sel.dispatchEvent(new Event('change',{bubbles:true}));sync()});sel.addEventListener('change',sync)}let step=0,steps=$$('.booking-step',form),titles=['Select swimmer category','Swimmer information','Choose a programme','Choose a batch','Set your schedule','Contact information','Fee information','Review and confirm'];let names=['category','swimmer','dob','gender','experience','guardian','program','level','goals','batch','coach','facility','startDate','frequency','preferredDays','contact','email','phone','emergency','address','notes','paymentMethod'];function val(n){return form.elements[n]?.value||''}function show(){steps.forEach((s,i)=>s.classList.toggle('active',i===step));$$('#bookingProgress span').forEach((s,i)=>s.classList.toggle('active',i<=step));$('#bookingStepLabel').textContent=`Step ${step+1} of 8`;$('#bookingStepTitle').textContent=titles[step];$('#bookingBack').disabled=step===0;$('#bookingNext').classList.toggle('d-none',step===7);$('#bookingSubmit').classList.toggle('d-none',step!==7);if(step===6){let p=D.programs.find(x=>x.title===val('program'));let amount=p?Number(String(p.fee).replace(/[^0-9.]/g,'')):0;let registration=25;$('#feeBreakdown').innerHTML=`<div class="d-flex justify-content-between py-2" style="border-bottom:1px solid var(--line)"><span>Programme fee · ${p?p.title:'To be confirmed'}</span><strong>${p?p.fee:'TBC'}</strong></div><div class="d-flex justify-content-between py-2" style="border-bottom:1px solid var(--line)"><span>Registration fee</span><strong>$${registration}</strong></div><div class="d-flex justify-content-between py-2"><span>Total</span><strong style="font:700 20px Sora;color:var(--ocean)">${p?'$'+(amount+registration):'To be confirmed'}</strong></div>`}if(step===7){$('#bookingReview').innerHTML=names.map(n=>{let v=val(n);return v?`<div class="d-flex justify-content-between py-2" style="border-bottom:1px solid var(--line)"><span class="text-capitalize" style="color:var(--muted)">${n.replace(/[A-Z]/g,m=>' '+m.toLowerCase())}</span><strong>${v}</strong></div>`:''}).join('')}}function validateStep(){let valid=true;steps[step].querySelectorAll('[required]').forEach(el=>{if(!el.checkValidity()){el.reportValidity();valid=false}});return valid}$('#bookingNext').addEventListener('click',()=>{if(!validateStep())return;step=Math.min(7,step+1);show()});$('#bookingBack').addEventListener('click',()=>{step=Math.max(0,step-1);show()});form.addEventListener('submit',e=>{e.preventDefault();if(!validateStep())return;if(!$('#bookingTerms').checked){$('#bookingTerms').reportValidity();return}let obj={};names.forEach(n=>obj[n]=val(n));localStorage.setItem('wavecrestLastBooking',JSON.stringify(obj));location.href=PG+'booking-confirmation.html'});let batchSelect=form.elements.batch,programSelect=form.elements.program,categorySelect=form.elements.category;function refreshBatches(){if(!batchSelect)return;let selected=val('program');let available=D.batches.filter(b=>b.status!=='Full'&&(!selected||b.program===selected));batchSelect.innerHTML='<option value="">Choose a batch</option>'+available.map(b=>`<option value="${b.day} · ${b.time} · ${b.program} · ${b.coach}">${b.day} · ${b.time} — ${b.program} with ${b.coach} (${b.seats} seats)</option>`).join('');if(!available.length)batchSelect.innerHTML+='<option value="" disabled>No batch listed — contact the academy</option>'}function refreshPrograms(){let category=val('category'),options=D.programs.filter(p=>!category||p.group===category);programSelect.innerHTML='<option value="">Choose programme</option>'+options.map(p=>`<option value="${p.title}">${p.title}</option>`).join('');refreshBatches()}function updateGuardianRequirement(){let g=form.elements.guardian;if(g)g.required=['Kids','Teens'].includes(val('category'))}categorySelect?.addEventListener('change',()=>{updateGuardianRequirement();refreshPrograms()});programSelect?.addEventListener('change',refreshBatches);let q=new URLSearchParams(location.search).get('program');if(q){let found=D.programs.find(p=>p.id===q);if(found){if(categorySelect)categorySelect.value=found.group;refreshPrograms();programSelect.value=found.title;refreshBatches();updateGuardianRequirement()}}else{refreshPrograms();updateGuardianRequirement()}show()}
