function initScroll(){
 const bar=document.createElement('div');bar.className='scroll-progress';document.body.appendChild(bar);
 let tick=false;const upd=()=>{const h=document.documentElement.scrollHeight-innerHeight;bar.style.transform=`scaleX(${h>0?Math.min(1,scrollY/h):0})`;tick=false};
 addEventListener('scroll',()=>{if(!tick){tick=true;requestAnimationFrame(upd)}},{passive:true});upd();
 if(matchMedia('(prefers-reduced-motion: reduce)').matches)return;
 const sel='.section-pad .eyebrow,.section-pad .section-title,.section-pad .section-copy,.content-card,.program-card,.testimonial,.feature-photo,.schedule-preview,.soft-panel,.trust-item,.progress-step,.gallery-grid>*,.cta-band>*,.feature-list>article';
 const els=[...document.querySelectorAll(sel)].filter(el=>!el.closest('#siteHeader,#siteFooter,.booking-step,.lightbox'));
 const counts=new Map();
 const obs=new IntersectionObserver(entries=>entries.forEach(e=>{if(!e.isIntersecting)return;const el=e.target;obs.unobserve(el);el.classList.add('in');setTimeout(()=>{el.classList.remove('rv','in');el.style.removeProperty('--d')},1400)}),{threshold:.12,rootMargin:'0px 0px -6% 0px'});
 els.forEach(el=>{const par=el.parentElement;const n=counts.get(par)||0;counts.set(par,n+1);el.style.setProperty('--d',Math.min(n,5)*90+'ms');el.classList.add('rv');obs.observe(el)});
}
